def solve(rows):
    # Filter rows where depot is 'bravo' or 'delta'
    filtered_rows = [row for row in rows if row['depot'] in ['bravo', 'delta']]

    # Sort rows by distance_km descending, then day ascending, then trip_id ascending
    sorted_rows = sorted(filtered_rows, key=lambda x: (-x['distance_km'], x['day'], x['trip_id']))

    # Extract unique days
    unique_days = set(row['day'] for row in sorted_rows)

    if not unique_days:
        return [0, None]

    # Find the longest consecutive block of days
    max_length = 1
    current_length = 1
    start_day = list(unique_days)[0]

    for day in sorted(unique_days):
        if day == start_day:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = day
                current_length = 1
            else:
                current_length = 1

    if max_length == 1:
        return [0, None]
    else:
        return [max_length, start_day]
