def solve(rows):
    # Filter rows where outcome is not 'no_show'
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']

    # Sum duration_min per doctor
    doctor_duration = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor in doctor_duration:
            doctor_duration[doctor] += duration
        else:
            doctor_duration[doctor] = duration

    # Sort doctors by total duration (descending), then alphabetically (ascending)
    sorted_doctors = sorted(doctor_duration.items(), key=lambda x: (-x[1], x[0]))

    # Check if there are at least two doctors
    if len(sorted_doctors) >= 2:
        return sorted_doctors[1]
    else:
        return None
