def solve(rows):
    # Keep only rows where outcome is 'completed'
    completed_rows = [row for row in rows if row['outcome'] == 'completed']

    # Extract distinct doctors
    doctors = set(row['doctor'] for row in completed_rows)
    if not doctors:
        return [0, None]

    # Calculate median duration_min for each doctor
    doctor_median = {}
    for doctor in doctors:
        durations = [row['duration_min'] for row in completed_rows if row['doctor'] == doctor]
        durations.sort()
        n = len(durations)
        if n % 2 == 1:
            median = (durations[n // 2] + durations[n // 2 + 1]) / 2
        else:
            median = (durations[n // 2 - 1] + durations[n // 2]) / 2

        # Round to one decimal place
        doctor_median[doctor] = round(median, 1)

    # Return the result
    return list(doctor_median.items())
