def solve(rows):
    filtered_rows = [row for row in rows if row['site'] in ['gwangju', 'incheon']]
    site_units_weight = {}
    for row in filtered_rows:
        site = row['site']
        units_weight = row['units'] * row['weight_kg']
        if site not in site_units_weight:
            site_units_weight[site] = 0
        site_units_weight[site] += units_weight

    max_value = None
    best_site = None
    for site in sorted(site_units_weight.keys()):
        value = site_units_weight[site]
        if value > max_value or (value == max_value and best_site is None):
            max_value = value
            best_site = site

    return [best_site] if max_value is not None else None
