def solve(rows):
    # Filter rows where day is 22 or less
    filtered_rows = [row for row in rows if row['day'] <= 22]

    # Sum duration_min per doctor
    doctor_duration = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor in doctor_duration:
            doctor_duration[doctor] += duration
        else:
            doctor_duration[doctor] = duration

    # Compute median duration for each doctor
    median_duration = {}
    for doctor, total in doctor_duration.items():
        # Sort and find median
        sorted_durations = sorted([total])
        n = len(sorted_durations)
        if n % 2 == 1:
            median = sorted_durations[n // 2]
        else:
            median = (sorted_durations[n // 2 - 1] + sorted_durations[n // 2]) / 2

        # Round to one decimal place
        median_rounded = round(median, 1)
        median_duration[doctor] = median_rounded

    # Return the second ranked doctor by median duration
    # Sort doctors by median duration (descending), then alphabetically (ascending)
    sorted_doctors = sorted(median_duration.items(), key=lambda x: (-x[1], x[0]))

    # Get the second ranked doctor
    if len(sorted_doctors) >= 2:
        return sorted_doctors[1][0]
    else:
        return None
