            if min_balance == 0:
                min_balance = balance
                min_day = row['day']
            else:
                if balance < min_balance:
                    min_balance = balance
                    min_day = row['day']

    if min_balance != 0:
        return [min_balance, min_day]
    else:
        return [0, None]
