def solve(rows):
    # Calculate the total number of late trips
    total_late = sum(1 for row in rows if row['result'] == 'late')

    # Group the trips by depot
    depot_groups = {}
    for row in rows:
        depot = row['depot']
        if depot not in depot_groups:
            depot_groups[depot] = []
        depot_groups[depot].append(row)

    # Calculate the percentage for each depot
    percentage_data = []
    for depot, trips in depot_groups.items():
        count_late = sum(1 for trip in trips if trip['result'] == 'late')
        total_trips = len(trips)
        if total_trips == 0:
            percentage = 0.0
        else:
            percentage = round(100 * count_late / total_trips, 1)
        if percentage >= 30:
            percentage_data.append((percentage, depot))

    # Sort by percentage (descending) and then by depot (alphabetically)
    percentage_data.sort(key=lambda x: (-x[0], x[1]))

    # Prepare the result
    result = []
    for val, depot in percentage_data:
        result.append((val, depot))

    return result
