def solve(rows):
    # Calculate the total number of shipped rows
    total_shipped = sum(1 for row in rows if row["phase"] == "shipped")

    # Group rows by site
    site_groups = {}
    for row in rows:
        site = row["site"]
        if site not in site_groups:
            site_groups[site] = []
        site_groups[site].append(row)

    # Calculate percentage for each site
    site_percentages = {}
    for site, rows in site_groups.items():
        shipped_count = sum(1 for row in rows if row["phase"] == "shipped")
        total_rows = len(rows)
        if total_rows == 0:
            percentage = 0.0
        else:
            percentage = (shipped_count / total_rows) * 100
        site_percentages[site] = (shipped_count, percentage)

    # Filter percentages >= 20%
    filtered_percentages = [
        (value, percentage) for site, (value, percentage) in site_percentages.items()
        if percentage >= 20.0
    ]

    # Sort by percentage (descending) and value (alphabetically)
    filtered_percentages.sort(key=lambda x: (-x[1], x[0]))

    return filtered_percentages
```

