    department_groups = defaultdict(list)
    for row in rows:
        department_groups[row['department']].append(row)

    # Calculate the number of no-show rows for each department
    no_show_counts = {dept: len(group) for dept, group in department_groups.items()}

    # Calculate total rows in each department
    total_rows = {dept: len(group) for dept, group in department_groups.items()}

    # Calculate percentage for each department
    percentages = {}
    for dept, count in no_show_counts.items():
        total = total_rows[dept]
        if total == 0:
            percentage = 0
        else:
            percentage = round(100 * count / total, 1)
        percentages[dept] = percentage

    # Filter percentages >= 35%
    filtered_percentages = {dept: perc for dept, perc in percentages.items() if perc >= 35}

    # Prepare the result: [value, percentage] pairs
    result = []
    for dept, perc in filtered_percentages.items():
        result.append((dept, perc))

    # Sort by percentage (descending) and then by value (alphabetically)
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
