def solve(rows):
    filtered_rows = [row for row in rows if row["weight_kg"] < 153]
    days = [row["day"] for row in filtered_rows]
    if not days:
        return [0, None]
    max_length = 1
    start_day = days[0]
    current_length = 1
    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
                start_day = days[i - current_length + 1]
        else:
            current_length = 1
    if max_length == 1:
        return [0, None]
    return [max_length, start_day]
```

