def solve(rows):
    filtered_rows = [row for row in rows if row['units'] >= 8]
    if not filtered_rows:
        return None

    total_units_weight = {}
    for row in filtered_rows:
        site = row['site']
        units = row['units']
        weight_kg = row['weight_kg']
        total_units_weight[site] = total_units_weight.get(site, 0) + units * weight_kg

    max_total = max(total_units_weight.values())
    candidates = [site for site, total in total_units_weight.items() if total == max_total]

    return min(candidates)
```

