def solve(rows):
    # Filter rows where day is 15 or less
    filtered_rows = [row for row in rows if row['day'] <= 15]

    if not filtered_rows:
        return None

    # Calculate total (packages * distance_km) for each depot
    depot_totals = {}
    for row in filtered_rows:
        depot = row['depot']
        total = row['packages'] * row['distance_km']
        if depot not in depot_totals:
            depot_totals[depot] = 0
        depot_totals[depot] += total

    # Find the depot with the highest total, breaking ties by alphabetical order
    max_total = -1
    best_depot = None
    for depot in sorted(depot_totals.keys()):
        if depot_totals[depot] > max_total:
            max_total = depot_totals[depot]
            best_depot = depot

    return best_depot
