def solve(rows):
    # Filter rows where site is 'busan' or 'incheon'
    filtered_rows = [row for row in rows if row['site'] in ['busan', 'incheon']]

    # Group by carrier and calculate median units
    from statistics import median

    carrier_units = {}
    for row in filtered_rows:
        carrier = row['carrier']
        units = row['units']
        if carrier in carrier_units:
            carrier_units[carrier].append(units)
        else:
            carrier_units[carrier] = [units]

    # Calculate median for each carrier
    carrier_medians = {}
    for carrier, units_list in carrier_units.items():
        median_units = median(units_list)
        carrier_medians[carrier] = round(median_units, 1)

    # Return the median of the rounded units
    if not carrier_medians:
        return 0.0
    medians = list(carrier_medians.values())
    return round(median(medians), 1)
