def solve(rows):
    # Group rows by depot
    depot_groups = {}
    for row in rows:
        depot = row['depot']
        if depot not in depot_groups:
            depot_groups[depot] = []
        depot_groups[depot].append(row)

    # Calculate percentage for each depot
    result_late_rows = {}
    for depot, depot_rows in depot_groups.items():
        late_count = sum(1 for row in depot_rows if row['result'] == 'late')
        total_rows = len(depot_rows)
        if total_rows == 0:
            result_late_rows[depot] = 0.0
        else:
            percentage = round(100 * late_count / total_rows, 1)
            result_late_rows[depot] = percentage

    # Filter percentages >= 30 and sort
    filtered = [val for val in result_late_rows.values() if val >= 30]
    filtered.sort(reverse=True)

    # Prepare result
    result = []
    for val in filtered:
        depot = [k for k, v in result_late_rows.items() if v == val][0]
        result.append((val, depot))

    return result
