    sorted_drivers = sorted(packages_per_driver.items(), key=lambda x: (-x[1], x[0]))

    # Filter drivers with total packages >= 2
    filtered_drivers = [driver for driver, total in sorted_drivers if total >= 2]

    # Find the second ranked driver
    if len(filtered_drivers) >= 2:
        second_driver = filtered_drivers[1]
        return second_driver
    else:
        return None
